          "import heapq",
          "",
          "class Solution:",
          "    def minMergeCost(self, files: list[int]) -> int:",
          "        # Optimal Min-Heap (Greedy) - O(n log n) Time | O(n) Space",
          "        heapq.heapify(files)",
          "        total_cost = 0",
          "",
          "        while len(files) > 1:",
          "            first = heapq.heappop(files)",
          "            second = heapq.heappop(files)",
          "            merged = first + second",
          "            total_cost += merged",
          "            heapq.heappush(files, merged)",
          "",
          "        return total_cost",
