          "    def solveRecursion(self, n: int = 6) -> int:",
          "        # Optimal Memoized / Iterative - O(n) Time | O(1) Space",
          "        if n <= 1:",
          "            return n",
          "        a, b = 0, 1",
          "        for _ in range(2, n + 1):",
          "            a, b = b, a + b",
          "        return b",
          "",
