          "    def solveString(self, s: str = \"racecar\") -> bool:",
          "        # Optimal Two Pointers - O(n) Time | O(1) Space",
          "        l, r = 0, len(s) - 1",
          "        while l < r:",
          "            if s[l] != s[r]:",
          "                return False",
          "            l += 1",
          "            r -= 1",
          "        return True",
